  let r = vec3f(0.0, 0.0, 1.0);
  let ambient = 0.3;
  let diffuse = 0.6;
  let specular = 0.5;
  let shininess = 50.0;
  let n = normalize(in.vN);
  let lightPosition = vec3f(0.0, 10.0, 5.0);
  let l = normalize(lightPosition);
  var df = max(0.0, dot(n, l));
  var sf = pow(max(dot(reflect(-l, n), r), 0.0), shininess);
